def calculate_S(N):
    """Calculates S(N) = sum_{a=1}^N sum_{b=1}^N floor(ab/(N+1))."""
    S = 0
    N_plus_1 = N + 1
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // N_plus_1
    return S

def calculate_T(N):
    """Calculates the target value T(N) = (N^3 - N^2 + 2) / 4."""
    return (N**3 - N**2 + 2) / 4

results = {}
for N in range(1, 6):
    S_N = calculate_S(N)
    T_N = calculate_T(N)
    results[N] = {
        "S(N)": S_N,
        "T(N)": T_N,
        "Match": S_N == T_N
    }

for N, res in results.items():
    print(f"N={N}: S(N)={res['S(N)']}, T(N)={res['T(N)']}, Match={res['Match']}")

